public with sharing class OpportunityStageHandler {
    // Keeps renewal opportunities in sync when a deal closes.
    public static void afterUpdate(List<Opportunity> records, Map<Id, Opportunity> oldMap) {
        List<Task> followUps = new List<Task>();
        for (Opportunity opp : records) {
            Opportunity previous = oldMap.get(opp.Id);
            if (opp.IsWon && !previous.IsWon) {
                followUps.add(new Task(
                    WhatId = opp.Id,
                    OwnerId = opp.OwnerId,
                    Subject = 'Kickoff call with customer',
                    ActivityDate = Date.today().addDays(7)
                ));
            }
        }
        if (!followUps.isEmpty()) {
            insert followUps;
        }
    }
}

public with sharing class CaseEscalationService {
    public static final Integer HIGH_PRIORITY_HOURS = 4;

    /* Escalates open high-priority cases that have breached the response window. */
    public static List<Case> findBreached(Datetime now) {
        Datetime cutoff = now.addHours(-HIGH_PRIORITY_HOURS);
        return [
            SELECT Id, CaseNumber, Subject, OwnerId
            FROM Case
            WHERE IsClosed = false AND Priority = 'High' AND CreatedDate < :cutoff
        ];
    }
}

public class LeadRoutingUtil {
    public static Id ownerFor(Lead l) {
        if (l.Country == 'United Kingdom') {
            return [SELECT Id FROM User WHERE Alias = 'salva' LIMIT 1].Id;
        }
        return UserInfo.getUserId();
    }
}
